from pydantic import BaseModel, Field, ValidationError
from typing import Optional

class OrderIn(BaseModel):
    order_id: str
    amount: float = Field(gt=0)            # must be > 0
    status: str = "pending"
    note: Optional[str] = None

# Good (but messy) record: amount is a string, coerced to float
good = {"order_id": "A1", "amount": "19.99", "status": "paid"}
order = OrderIn.model_validate(good)
print(order)
print(order.model_dump())

# Bad record: missing order_id, negative amount
bad = {"amount": -5}
try:
    OrderIn.model_validate(bad)
except ValidationError as e:
    print("errors:", e.error_count())
    for err in e.errors():
        print(err["loc"], err["msg"])

from pydantic import BaseModel, field_validator, ConfigDict, ValidationError

class Event(BaseModel):
    model_config = ConfigDict(extra="forbid")  # reject unknown fields

    event_id: str
    source: str

    @field_validator("source")
    @classmethod
    def normalize_source(cls, v: str) -> str:
        v = v.strip().lower()
        if not v:
            raise ValueError("source must not be blank")
        return v

raw_batch = [
    {"event_id": "e1", "source": "  CRM "},
    {"event_id": "e2", "source": ""},              # blank -> invalid
    {"event_id": "e3", "source": "api", "oops": 1}, # extra field -> invalid
]

valid, quarantine = [], []
for rec in raw_batch:
    try:
        valid.append(Event.model_validate(rec))
    except ValidationError as e:
        quarantine.append((rec, e.error_count()))

print("valid:", [e.model_dump() for e in valid])
print("quarantined:", quarantine)
